    ```typescript
    import { Component, inject, signal } from '@angular/core';
    import { ActivatedRoute } from '@angular/router';
    import { DatePipe } from '@angular/common';
    import { HttpErrorResponse } from '@angular/common/http';

    import { EventsApiService } from '../../core/api/events-api.service';
    import { EventDetail } from '../../core/api/event-detail';

    @Component({
      selector: 'app-event-detail',
      imports: [DatePipe],
      templateUrl: './event-detail.html',
      styleUrl: './event-detail.scss'
    })
    export class EventDetailPage {
      private readonly route = inject(ActivatedRoute);
      private readonly eventsApi = inject(EventsApiService);

      readonly event = signal<EventDetail | null>(null);
      readonly loading = signal(true);
      readonly notFound = signal(false);
      readonly loadError = signal(false);

      constructor() {
        const id = Number(this.route.snapshot.paramMap.get('id'));
        if (!Number.isInteger(id)) {
          this.loading.set(false);
          this.notFound.set(true);
          return;
        }

        this.eventsApi.getEvent(id).subscribe({
          next: event => {
            this.event.set(event);
            this.loading.set(false);
          },
          error: (err: HttpErrorResponse) => {
            this.loading.set(false);
            if (err.error?.code === 'EVENT_NOT_FOUND') {
              this.notFound.set(true);
            } else {
              this.loadError.set(true);
            }
          }
        });
      }
    }
    ```
    Route-Parameter wird bewusst per `route.snapshot.paramMap.get('id')` im Konstruktor gelesen, nicht reaktiv (kein `toSignal(route.paramMap)`) `[ANNAHME]`: Diese Seite ist im gesamten IA-Baum (`EXPERIENCE.md` → Information Architecture) nur von `event-card` aus erreichbar, es gibt keinen Link von einer Detailseite zu einer anderen — ein Navigations-Fall, bei dem Angular dieselbe Komponenteninstanz mit geändertem `id`-Parameter wiederverwendet, kommt in dieser Anwendung nicht vor. `provideRouter` in `app.config.ts` nutzt kein `withComponentInputBinding()`, daher kein `@Input() id`-Pattern verfügbar/etabliert — `ActivatedRoute` ist der einzige Weg.
    Fehlerunterscheidung nach `err.error?.code`, nicht nach `message` oder HTTP-Status — folgt AD-7 ("Frontend schaltet ausschließlich auf `code`, nie auf `message`") und ist bereits jetzt so anzulegen, auch wenn diese Story der erste Ort ist, an dem ein Fehlercode überhaupt im Frontend ausgewertet wird.
